import {createStockEvidenceController} from './stock-evidence.js';
import {mountFundamentalBrief} from './fundamental-brief.js';
import {mountBusinessProfile} from './business-profile.js';
import {mountEarningsSurprise} from './earnings-surprise.js';
import {mountEarningsInflection} from './earnings-inflection.js';
import {mountDartFilings} from './dart-filings.js';
import {mountAnalystOpinions} from './analyst-opinions.js';
import {mountSecFilings} from './sec-filings.js';
import {escapeHtml as esc} from './components.js';
import {openPdfViewer} from './pdf-viewer.js';
import {mountFinancials} from './financial-view.js';
import {priceEvents,selectEvents,sortedReports,changeLabels} from './research-model.js';
import {eventMarkup,coverageMarkup,fetchResearch,pct,number,updated,safeLink,showEventHistory} from './research-view.js';
export function mountStockResearch(root,{market,ticker,onChartDate,navigate,onIdentity,onEvents}){
 const controller=new AbortController(),signal=controller.signal;let data=null,prices=[],kind='all',sort='latest',tab=new URLSearchParams(location.search).get('tab')||'company',viewer,financial,filings,evidence,version=0;
 root.className='stock-research';root.innerHTML=`<section class="surface fundamental-brief" id="fundamental-brief" aria-label="기업 분석"></section><details class="surface fundamental-reference"><summary>실적 흐름 · 상세 신호</summary><div class="inflection-host"></div></details><section class="surface recent-changes" aria-labelledby="recent-title"><div class="research-heading"><div><h2 id="recent-title">최근 변화</h2><p>자료별 변화를 한곳에서</p></div><button data-research-refresh>새로고침</button></div><div class="research-filters" role="group" aria-label="최근 변화 종류">${[['all','전체'],['earnings','실적·일정'],['report','리포트'],['price','주가']].map(([v,l])=>`<button data-research-kind="${v}" aria-pressed="${v===kind}">${l}</button>`).join('')}</div><div class="research-timeline" aria-live="polite"><p>최근 변화를 불러오는 중입니다</p></div><p class="research-note">같은 날짜의 일정·리포트와 가격 변동은 인과관계를 뜻하지 않습니다. 주가 항목은 일봉 종가 변동 ±5% 이상입니다.</p><div class="research-coverage"></div></section><details class="surface fundamental-reference" data-business-reference><summary>사업·매출 구조 · 전체 항목과 원문</summary><section class="business-profile"></section></details><div class="research-tabs" role="tablist" aria-label="종목 상세 정보">${[['company','기업 정보'],['financial','실적·재무'],['reports','리포트'],['filings','공시']].map(([v,l])=>`<button id="research-tab-${v}" role="tab" data-research-tab="${v}" aria-controls="research-panel-${v}">${l}</button>`).join('')}</div>${['company','financial','reports','filings'].map(v=>`<section id="research-panel-${v}" class="surface research-panel" role="tabpanel" aria-labelledby="research-tab-${v}"></section>`).join('')}`;
 const recent=root.querySelector('.recent-changes'),disclosure=document.createElement('details');disclosure.className='surface recent-disclosure';disclosure.innerHTML='<summary>최근 변화 · 일정과 리포트 함께 보기</summary>';root.append(disclosure);disclosure.append(recent);
 const brief=mountFundamentalBrief(root.querySelector('.fundamental-brief'),{market,ticker,onRetry(){financial.load(true);businessProfile.load();load();evidence?.refresh();},onCollect(){void evidence?.collect();},onOpenBusiness(evidence){const details=root.querySelector('[data-business-reference]');details.open=true;if(evidence)businessProfile.openEvidence(evidence);else details.scrollIntoView({block:'start'});},onOpenFinancial(){activate('financial');$('#research-panel-financial').scrollIntoView({block:'start'});},onOpenReports(){activate('reports');$('#research-panel-reports').scrollIntoView({block:'start'});},onOpenFilings(){activate('filings');$('#research-panel-filings').scrollIntoView({block:'start'});}});
 const businessProfile=mountBusinessProfile(root.querySelector('.business-profile'),{market,ticker,onData:(data,status)=>brief.setBusiness(data,status)});
 const inflection=mountEarningsInflection(root.querySelector('.inflection-host'),{market,ticker});
 const $=s=>root.querySelector(s);$('#research-panel-financial').innerHTML='<section class=surprise-host></section><div class=financial-dashboard></div><section class=analyst-opinions></section>';const surprise=mountEarningsSurprise($('.surprise-host'),{market,ticker});const opinions=mountAnalystOpinions($('.analyst-opinions'),{navigate});financial=mountFinancials({company:$('#research-panel-company'),financial:$('.financial-dashboard'),market,ticker,onData:(data,status)=>brief.setFinancial(data,status),onNotApplicable(){$('.inflection-host').closest('details').hidden=true;inflection.destroy();surprise.destroy();root.querySelector('[data-research-tab="financial"]').hidden=true;if(tab==='financial')activate('company');},onIdentity(profile){onIdentity?.(profile);load();}});
 evidence=createStockEvidenceController({market,ticker,onState:state=>brief.setEnrichment(state),onRefresh:()=>Promise.all([financial.load(true),businessProfile.load(true),load()])});void evidence.start();
 function activate(next){tab=['company','financial','reports','filings'].includes(next)?next:'company';root.querySelectorAll('[data-research-tab]').forEach(b=>{b.setAttribute('aria-selected',String(b.dataset.researchTab===tab));b.tabIndex=b.dataset.researchTab===tab?0:-1;});root.querySelectorAll('.research-panel').forEach(p=>p.hidden=p.id!=='research-panel-'+tab);filings?.setVisible(tab==='filings');if(tab==='financial'||tab==='company')financial.load();const p=new URLSearchParams(location.search);p.set('tab',tab);history.replaceState(history.state,'',location.pathname+'?'+p);}
 function timeline(){const events=selectEvents([...new Map([...prices,...(data?.items||[])].map(e=>[e.id,e])).values()],{kind});$('.research-timeline').innerHTML=events.length?events.map(e=>eventMarkup(e,{compactReports:true,report:data?.reports?.find(r=>r.id===e.reportId)})).join(''):'<p class="research-empty">해당 기간에 확인된 변화가 없습니다.</p>';root.querySelectorAll('[data-research-kind]').forEach(b=>b.setAttribute('aria-pressed',String(kind===b.dataset.researchKind)));$('.research-coverage').innerHTML=coverageMarkup(data?.coverage);}
 function reports(){const items=sortedReports(data?.reports||[],sort);$('#research-panel-reports').innerHTML=`<div class="research-heading"><h2>증권사 리포트 <small>${items.length}건</small></h2><select aria-label="리포트 비교 정렬" data-research-sort><option value="latest">최신순</option><option value="target">목표주가순 · 통화별</option><option value="up">상향 발표순</option></select></div>${items.length?`<div class="research-table-scroll" tabindex="0" role="region" aria-label="증권사 리포트 비교"><table class="research-table"><thead><tr><th>증권사 · 발행일</th><th>보고서</th><th>투자의견</th><th>목표주가</th><th>직전 리포트 대비</th></tr></thead><tbody>${items.map(r=>`<tr><td data-label="증권사 · 발행일"><strong>${esc(r.broker||'확인 불가')}</strong><small>${esc(r.date||'발행일 확인 불가')}</small></td><td data-label="보고서"><button data-research-report="${esc(r.id)}">${esc(r.title)}</button></td><td data-label="투자의견">${esc(r.rating||'의견 미기재')}</td><td data-label="목표주가">${r.target?number(r.target.value)+' '+esc(r.target.currency):'목표주가 미기재'}</td><td data-label="직전 리포트 대비"><b class="report-target-${esc(r.revision||'none')}">${({up:'상향',down:'하향',unchanged:'유지'}[r.revision])||'비교 불가'}</b>${r.previousTarget?`<small>${r.previousTarget.date} · ${number(r.previousTarget.value)} ${r.previousTarget.currency}</small>`:r.explicitRevision?`<small class="report-target-${esc(r.explicitRevision)}">보고서 표기: ${r.explicitRevision==='up'?'상향':'하향'}</small>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<p class="research-empty">연결된 종목 리포트가 없습니다.</p>'}<p class="research-note">같은 증권사·같은 통화의 직전 발행 리포트와 비교합니다. 발행일·목표주가가 확인되지 않으면 비교하지 않습니다.</p>`;$('[data-research-sort]').value=sort;}
 async function load(){const n=++version;try{const next=await fetchResearch([market+':'+ticker],signal);if(signal.aborted||n!==version)return;data=next;brief.setReports(data.reports);opinions.set(data.reports,data.coverage?.reports);onEvents?.(data.items||[]);timeline();reports();}catch(e){if(!signal.aborted){$('.research-timeline').innerHTML='<p class="research-empty">최근 변화 연결 오류 · 새로고침으로 다시 확인해 주세요.</p>';$('.research-coverage').textContent=e.message;reports();}}}
 function openReport(id){const r=data?.reports?.find(r=>r.id===id);if(r?.attachment?.url){viewer?.close();viewer=openPdfViewer({...r,fields:{title:{value:r.title}}});}else navigate('/reports?report='+encodeURIComponent(id));}
 root.addEventListener('click',e=>{showEventHistory(e,signal);const b=e.target.closest('button');if(!b)return;if(b.dataset.researchKind){kind=b.dataset.researchKind;timeline();}if(b.dataset.researchTab)activate(b.dataset.researchTab);if(b.hasAttribute('data-research-refresh'))load();if(b.dataset.researchReport)openReport(b.dataset.researchReport);if(b.dataset.researchDate)onChartDate(b.dataset.researchDate);},{signal});
 root.addEventListener('keydown',e=>{if(!e.target.matches('[data-research-tab]')||!['ArrowLeft','ArrowRight'].includes(e.key))return;e.preventDefault();const tabs=[...root.querySelectorAll('[data-research-tab]')].filter(b=>!b.hidden),i=tabs.indexOf(e.target),b=tabs[(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length];b.click();b.focus();},{signal});
 root.addEventListener('change',e=>{if(e.target.matches('[data-research-sort]')){sort=e.target.value;reports();}},{signal});filings=(market==='US'?mountSecFilings:mountDartFilings)($('#research-panel-filings'),{ticker});activate(tab);financial.load();load();
 return {openReport,setQuote(stock,feed){brief.setQuote(stock,feed);prices=priceEvents(stock,feed);financial.setQuote(stock,feed);if(data)timeline();load();},destroy(){evidence.destroy();brief.destroy();businessProfile.destroy();inflection.destroy();surprise.destroy();controller.abort();viewer?.close();financial.destroy();opinions.destroy();filings?.destroy();}};
}
